-- Reference schema only. NOT an automatic migration of browser data.
PRAGMA foreign_keys = ON;
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL);
CREATE TABLE workspaces(id TEXT PRIMARY KEY,owner_user_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL);
CREATE TABLE memberships(workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('owner','admin','editor','viewer')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE stores(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,platform TEXT NOT NULL,UNIQUE(workspace_id,id));
CREATE TABLE products(id TEXT NOT NULL,workspace_id TEXT NOT NULL,store_id TEXT NOT NULL,name TEXT NOT NULL,data_json TEXT NOT NULL,PRIMARY KEY(workspace_id,store_id,id),FOREIGN KEY(workspace_id,store_id) REFERENCES stores(workspace_id,id));
CREATE TABLE conversations(id TEXT NOT NULL,workspace_id TEXT NOT NULL,store_id TEXT NOT NULL,product_id TEXT,external_id TEXT,assigned_user_id TEXT REFERENCES users(id),human_required INTEGER NOT NULL DEFAULT 1 CHECK(human_required IN(0,1)),PRIMARY KEY(workspace_id,store_id,id),FOREIGN KEY(workspace_id,store_id) REFERENCES stores(workspace_id,id),FOREIGN KEY(workspace_id,store_id,product_id) REFERENCES products(workspace_id,store_id,id),UNIQUE(workspace_id,store_id,external_id));
CREATE TABLE messages(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,store_id TEXT NOT NULL,conversation_id TEXT NOT NULL,external_id TEXT,role TEXT NOT NULL CHECK(role IN('buyer','seller','assistant')),text TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(workspace_id,store_id,conversation_id) REFERENCES conversations(workspace_id,store_id,id),UNIQUE(workspace_id,store_id,external_id));
CREATE TABLE ai_settings(workspace_id TEXT NOT NULL,store_id TEXT NOT NULL,style TEXT NOT NULL,config_json TEXT NOT NULL,auto_enabled INTEGER NOT NULL DEFAULT 0 CHECK(auto_enabled IN(0,1)),PRIMARY KEY(workspace_id,store_id),FOREIGN KEY(workspace_id,store_id) REFERENCES stores(workspace_id,id));
CREATE TABLE training_examples(id TEXT NOT NULL,workspace_id TEXT NOT NULL,store_id TEXT NOT NULL,product_id TEXT NOT NULL,question TEXT NOT NULL,original_reply TEXT NOT NULL,corrected_reply TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('approved','edited','rejected','pending')),comment TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(workspace_id,store_id,id),FOREIGN KEY(workspace_id,store_id,product_id) REFERENCES products(workspace_id,store_id,id));
CREATE TABLE training_revisions(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,store_id TEXT NOT NULL,example_id TEXT NOT NULL,previous_json TEXT NOT NULL,changed_at TEXT NOT NULL,FOREIGN KEY(workspace_id,store_id,example_id) REFERENCES training_examples(workspace_id,store_id,id));
CREATE TABLE listings(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,store_id TEXT NOT NULL,product_id TEXT,content_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL,FOREIGN KEY(workspace_id,store_id) REFERENCES stores(workspace_id,id),FOREIGN KEY(workspace_id,store_id,product_id) REFERENCES products(workspace_id,store_id,id));
CREATE TABLE media_assets(id TEXT NOT NULL,workspace_id TEXT NOT NULL,store_id TEXT NOT NULL,storage_key TEXT NOT NULL UNIQUE,mime TEXT NOT NULL,size_bytes INTEGER NOT NULL CHECK(size_bytes>=0),created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,store_id,id),FOREIGN KEY(workspace_id,store_id) REFERENCES stores(workspace_id,id));
CREATE TABLE generation_jobs(id TEXT NOT NULL,workspace_id TEXT NOT NULL,store_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('photo','video','listing')),status TEXT NOT NULL CHECK(status IN('queued','processing','waiting_provider','completed','failed','cancelled')),idempotency_key TEXT NOT NULL,config_json TEXT NOT NULL,error_code TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(workspace_id,store_id,id),FOREIGN KEY(workspace_id,store_id) REFERENCES stores(workspace_id,id),UNIQUE(workspace_id,store_id,idempotency_key));
CREATE TABLE job_assets(workspace_id TEXT NOT NULL,store_id TEXT NOT NULL,job_id TEXT NOT NULL,asset_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('source','output')),PRIMARY KEY(workspace_id,store_id,job_id,asset_id,role),FOREIGN KEY(workspace_id,store_id,job_id) REFERENCES generation_jobs(workspace_id,store_id,id),FOREIGN KEY(workspace_id,store_id,asset_id) REFERENCES media_assets(workspace_id,store_id,id));
CREATE TABLE usage_records(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,store_id TEXT NOT NULL,request_id TEXT NOT NULL UNIQUE,provider TEXT NOT NULL,model_id TEXT NOT NULL,input_tokens INTEGER CHECK(input_tokens>=0),output_tokens INTEGER CHECK(output_tokens>=0),cost_amount REAL CHECK(cost_amount>=0),currency TEXT,created_at TEXT NOT NULL,FOREIGN KEY(workspace_id,store_id) REFERENCES stores(workspace_id,id));
CREATE TABLE subscription_plans(id TEXT PRIMARY KEY,name TEXT NOT NULL,limits_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)));
CREATE TABLE workspace_subscriptions(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id),plan_id TEXT NOT NULL REFERENCES subscription_plans(id),status TEXT NOT NULL DEFAULT 'disabled');
CREATE TABLE audit_events(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,store_id TEXT NOT NULL,actor_user_id TEXT REFERENCES users(id),action TEXT NOT NULL,entity_id TEXT,created_at TEXT NOT NULL,FOREIGN KEY(workspace_id,store_id) REFERENCES stores(workspace_id,id));
CREATE INDEX messages_by_store_time ON messages(workspace_id,store_id,created_at);
CREATE INDEX examples_by_product_status ON training_examples(workspace_id,store_id,product_id,status);
CREATE INDEX jobs_by_store_status ON generation_jobs(workspace_id,store_id,status,created_at);
CREATE INDEX usage_by_store_time ON usage_records(workspace_id,store_id,created_at);
